  "ui.wpAdminAgentFrameApp.feedback106": "현재 Gutenberg 문서는 바인딩된 청크 스냅샷으로만 사용할 수 있습니다. 필요한 모든 청크를 읽기 전에는 전체 문서 편집을 준비할 수 없습니다. 변경하지 않았습니다.",
  "ui.wpAdminAgentFrameApp.feedback107": "현재 Gutenberg 게시물에 저장되지 않은 변경 사항이 있습니다. Pixflow가 읽거나 콘텐츠 기반 편집을 준비하기 전에 저장 또는 업데이트하세요. 변경하지 않았습니다.",
