  "wp.message.26a6374fbf59": "Pixflow 추가 기능을 시작하지 못했습니다. Pixflow 플러그인의 호환성을 확인한 후 새로고침하세요. 다른 기능은 계속 사용할 수 있습니다.",
  "wp.message.ca7714cffbcc": "Pro 활성화",
  "wp.message.197c83a2f752": "Pro 추가 기능으로 프리미엄 도구를 복원하세요. 라이선스, 콘텐츠, 저장된 설정은 유지됩니다. Bricks 2단계 인증을 사용했다면 Pro 활성화 후 설정에서 다시 켜세요.",
  "wp.message.2ffdcbc380ea": "즐겨 쓰는 빌더에서 제작하세요. 워크플로에 주석, 음성, 디자인 시스템 및 이미지 생성을 추가하세요.",
  "wp.message.40ed1102964b": "Pro 체험 확인",
  "wp.message.e9cccd3ef5fc": "닫기 상태를 저장하지 못했습니다. 다시 시도하세요.",
  "wp.message.1372089fb797": "Pixflow Pro 배너 닫기",
